import{_ as e,o as i,c as o,a0 as n}from"./chunks/framework.TJhnt8t4.js";const k=JSON.parse('{"title":"Implementacija sopstvenog konektora","description":"","frontmatter":{},"headers":[],"relativePath":"sr/guide/custom-connector.md","filePath":"sr/guide/custom-connector.md"}'),t={name:"sr/guide/custom-connector.md"};function r(s,a,p,l,d,v){return i(),o("div",null,[...a[0]||(a[0]=[n(`<h1 id="implementacija-sopstvenog-konektora" tabindex="-1">Implementacija sopstvenog konektora <a class="header-anchor" href="#implementacija-sopstvenog-konektora" aria-label="Permalink to &quot;Implementacija sopstvenog konektora&quot;">​</a></h1><p>Korišćenje <a href="./android-sdk">Android</a> ili <a href="./ios-macos-sdk">iOS/macOS</a> SDK-a nije obavezno. Protokol koji oni implementiraju je javan i opisan ovde — klijent može preuzeti registar, proveriti ga i primeniti pinove bilo kojim HTTP/TLS stekom koji već koristi. Ovo je ista specifikacija koju prate oba zvanična SDK-a; kompletno kriptografsko obrazloženje je u odeljku <a href="./architecture">Arhitektura</a>.</p><h2 id="sta-vas-konektor-mora-da-radi" tabindex="-1">Šta vaš konektor mora da radi <a class="header-anchor" href="#sta-vas-konektor-mora-da-radi" aria-label="Permalink to &quot;Šta vaš konektor mora da radi&quot;">​</a></h2><ol><li><strong>Preuzeti</strong> registar preko HTTPS-a: <code>GET</code> na konfigurisan endpoint, parsirati JSON objekat na vrhu — <code>payload</code> i <code>signature</code>. Preuzeti sirovi JSON podstring <code>payload</code>-a tačno u obliku u kom je primljen, <strong>pre</strong> bilo kakve deserijalizacije. Upravo taj bajtovski string je pokriven potpisom; njegova ponovna serijalizacija (drugačiji redosled ključeva, drugačiji razmaci) učiniće proveru nevažećom.</li><li><strong>Kanonizovati</strong> taj sirovi string prema specifikaciji <a href="https://datatracker.ietf.org/doc/html/rfc8785" target="_blank" rel="noreferrer">JCS, RFC 8785</a>: sortirati ključeve objekta po Unicode code point-u, ukloniti nebitne razmake, primeniti standardna pravila serijalizacije brojeva i stringova.</li><li><strong>Heš-ovati</strong> kanonizovane bajtove algoritmom SHA-512.</li><li><strong>Proveriti</strong> polje <code>signature</code> (nakon Base64 dekodiranja) prema tom hešu algoritmom RSA PKCS#1 v1.5, koristeći javni ključ ugrađen u vašu aplikaciju (<code>pub.pem</code>, generisan zajedno sa ključem za potpisivanje na serveru — vidi <a href="./architecture#generisanje-kljuceva-za-potpisivanje">Generisanje ključeva za potpisivanje</a>). Prihvatite javni ključ u formatu koji vam odgovara za strategiju ugrađivanja: PEM, Base64-kodiran PEM, ili sirov DER (SPKI) — oba zvanična SDK-a podržavaju sva tri formata upravo iz tog razloga.</li><li><strong>Fail closed.</strong> Ako se potpis ne proverava uspešno, endpoint nije dostupan, ili je odgovor nepravilno formiran — ne kreirajte pinovani klijent i nemojte tiho preći na nepinovani. Prekinite inicijalizaciju ili pređite u degradiran režim, vidljiv korisniku. Nijedan zvanični SDK nikada ne kreira delimično proveren ili &quot;best-effort&quot; pinovani klijent — ovde nema bezbedne sredine.</li><li><strong>Primeniti pinove.</strong> Nakon uspešne provere deserijalizujte <code>payload.keys</code> i podesite pinning sertifikata/javnog ključa vašeg HTTP klijenta SHA-256 SPKI hešom iz polja <code>key</code> svakog zapisa, vezanim za njegov <code>domainName</code>. Tačne vrednosti polja — u odeljku <a href="./architecture#format-potpisanog-registra">Format potpisanog registra</a>.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vaša aplikacija</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├─ GET &lt;endpoint&gt;                         → { payload, signature }</span></span>
<span class="line"><span>   ├─ canonicalize(raw payload string)  [JCS]</span></span>
<span class="line"><span>   ├─ sha512(canonical)</span></span>
<span class="line"><span>   ├─ verify(signature, hash, embedded pubkey)  [RSA PKCS#1 v1.5]</span></span>
<span class="line"><span>   │    ├─ fail  → prekid / degradiran režim, bez pinovanog klijenta</span></span>
<span class="line"><span>   │    └─ pass  → raščlani payload.keys</span></span>
<span class="line"><span>   │                za svaki ključ: pinuj sha256(SPKI) na domainName</span></span>
<span class="line"><span>   │                u mehanizmu pinninga vašeg TLS/HTTP steka</span></span>
<span class="line"><span>   └─ gotovo</span></span></code></pre></div><h2 id="zasto-je-ovo-bezbedno-raditi-samostalno" tabindex="-1">Zašto je ovo bezbedno raditi samostalno <a class="header-anchor" href="#zasto-je-ovo-bezbedno-raditi-samostalno" aria-label="Permalink to &quot;Zašto je ovo bezbedno raditi samostalno&quot;">​</a></h2><p>Potpis registra je jedino što stoji između falsifikovanog i pouzdanog odgovora, i to je standardan RSA potpis nad standardnom šemom kanonizacije, a ne vlasnički protokol. Bilo koja platforma sa primitivom za proveru RSA potpisa i ispravnom implementacijom JCS-a može ga ispravno validirati. Oba zvanična SDK-a postoje radi pogodnosti (podešavanje HTTP klijenta, integracija sa API-jem za pinning) — a ne zato što sam protokol zahteva poverenje specifično za platformu.</p><h2 id="gde-naci-ostale-detalje" tabindex="-1">Gde naći ostale detalje <a class="header-anchor" href="#gde-naci-ostale-detalje" aria-label="Permalink to &quot;Gde naći ostale detalje&quot;">​</a></h2><ul><li>Endpoint registra i oblik odgovora: <a href="./self-hosting">Self-hosting</a> i <a href="./../reference/http-api">HTTP API</a>.</li><li>Tačna JSON šema koju kanonizujete i proveravate: <a href="./architecture#format-potpisanog-registra">Format potpisanog registra</a>.</li><li>Razrađena, za jezik specifična referentna implementacija svakog koraka iznad: izvorni kod <a href="./android-sdk">Android SDK-a</a> (Kotlin) i <a href="./ios-macos-sdk">Apple SDK-a</a> (Swift) su otvoreni — čitanje bilo kog od njih je brže nego iznova izvoditi RFC 8785 od nule, ako su vam potrebni bajtovski detalji.</li></ul>`,9)])])}const j=e(t,[["render",r]]);export{k as __pageData,j as default};
